using BillingRecon.Domain.Receivables;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BillingRecon.Infrastructure.Receivables;

/// <summary>
/// The <c>LedgerPostings</c> table (docs/database.md, section 3.7; BR-401, BR-402, BR-406). The id is generated by
/// the application, like every typed id. The kind and the document type are stored by name with their CHECK
/// constraints, and the tenant column with its filter, guard and foreign key come from the conventions of the
/// context. So do the two other foreign keys: to the payer, and to the posting a reversal reverses. Both columns
/// are typed ids, and the context gives every such column its key (ADR 0021), so this class names no entity of
/// another module. Rows are never updated or deleted: the entity is append-only.
/// </summary>
public sealed class LedgerPostingConfiguration : IEntityTypeConfiguration<LedgerPosting>
{
    private const int KindMaxLength = 30;
    private const int DocumentTypeMaxLength = 30;

    /// <inheritdoc />
    public void Configure(EntityTypeBuilder<LedgerPosting> builder)
    {
        builder.ToTable("LedgerPostings");
        builder.HasKey(posting => posting.Id);

        builder.Property(posting => posting.Kind).HasMaxLength(KindMaxLength);
        builder.Property(posting => posting.DocumentType).HasMaxLength(DocumentTypeMaxLength);
        builder.Property(posting => posting.Description).HasMaxLength(LedgerPosting.DescriptionMaxLength);

        builder.HasIndex(posting => new { posting.TenantId, posting.BusinessDate }).HasDatabaseName("IX_LedgerPostings_TenantId_BusinessDate");
        builder.HasIndex(posting => new { posting.TenantId, posting.DocumentType, posting.DocumentId })
            .HasDatabaseName("IX_LedgerPostings_TenantId_DocumentType_DocumentId");
        builder.HasIndex(posting => new { posting.TenantId, posting.PayerId }).HasDatabaseName("IX_LedgerPostings_TenantId_PayerId");

        // The postings of a shift: its expected cash (BR-312; ADR 0060). Most postings name none.
        builder.HasIndex(posting => new { posting.TenantId, posting.ShiftId })
            .HasFilter("[ShiftId] IS NOT NULL")
            .HasDatabaseName("IX_LedgerPostings_TenantId_ShiftId");

        // The entries belong to the posting and are written with it. Nothing ever takes one out again.
        builder.HasMany(posting => posting.Entries)
            .WithOne()
            .HasForeignKey(entry => entry.PostingId)
            .HasConstraintName("FK_LedgerEntries_PostingId");
        builder.Navigation(posting => posting.Entries).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}
